create role authenticated nologin;create role anon nologin;
create schema auth;create schema storage;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
grant usage on schema auth,storage to authenticated,anon;grant execute on function auth.uid() to authenticated,anon;
create table public.users(id uuid primary key,auth_uid uuid,role text,status text);
create table public.workers(id uuid primary key,name text);
create table public.sites(id uuid primary key,site_name text);
create table public.site_supervisors(site_id uuid,user_id uuid);
create function public.my_role() returns text language sql stable security definer as $$select role from public.users where auth_uid=auth.uid() and status='active' limit 1$$;
create function public.my_user_id() returns uuid language sql stable security definer as $$select id from public.users where auth_uid=auth.uid() and status='active' limit 1$$;
create function public.my_site_ids() returns setof uuid language sql stable security definer as $$select site_id from public.site_supervisors where user_id=public.my_user_id()$$;
create table storage.buckets(id text primary key,name text,public boolean,file_size_limit bigint,allowed_mime_types text[]);
create table storage.objects(id uuid default gen_random_uuid(),bucket_id text,name text,owner_id text);
alter table storage.objects enable row level security;
grant select on public.users,public.workers,public.sites,public.site_supervisors to authenticated;
grant select,insert,delete on storage.objects to authenticated;
